            <div class="seek-feedback" id="seekFeedback"></div>
            <div class="video-container">
                ${videoSource}
                ${fallbackIframe ? `<div class="fallback-notice">视频加载失败，已切换备用播放器</div>` : ''}
                ${fallbackIframe}
            </div>
