                </div>
            </div>

            <script>
                // 检测视频是否可播放
                function checkVideoPlayable() {
                    const video = document.getElementById('video');
                    if (!video) return true;

                    return new Promise((resolve) => {
                        video.addEventListener('error', () => {
                            resolve(false);
                        });

                        // 设置超时检测
                        setTimeout(() => {
                            if (video.readyState === 0) {
                                resolve(false);
                            } else {
                                resolve(true);
                            }
                        }, 3000);
                    });
                }

                // 初始化播放器
                async function initPlayer() {
                    const video = document.getElementById('video');
                    const fallbackIframe = document.getElementById('fallbackIframe');

                    if (video) {
                        const canPlay = await checkVideoPlayable();
                        if (!canPlay && fallbackIframe) {
                            video.style.display = 'none';
                            fallbackIframe.style.display = 'block';
                        }
                    }

                    // 添加控制逻辑
                    setupVideoControls();
                }

                // 视频控制逻辑
                function setupVideoControls() {
                    const video = document.getElementById('video');
                    if (!video) return;

                    const seekFeedback = document.getElementById('seekFeedback');
                    let touchStartX = 0;
                    let touchStartTime = 0;
                    let isSeeking = false;
                    let seekTimeout;

                    // 长按滑动快进（左滑后退，右滑前进）
                    video.addEventListener('touchstart', (e) => {
                        if (e.touches.length === 1) {
                            touchStartX = e.touches[0].clientX;
                            touchStartTime = video.currentTime;
                            isSeeking = true;
                        }
                    });

                    video.addEventListener('touchmove', (e) => {
                        if (!isSeeking || !video.duration || e.touches.length !== 1) return;

                        const touchX = e.touches[0].clientX;
                        const deltaX = touchX - touchStartX;
                        const seekDistance = deltaX / window.innerWidth;
                        const seekAmount = seekDistance * 30;

                        let newTime = touchStartTime + seekAmount;
                        newTime = Math.max(0, Math.min(newTime, video.duration));
                        video.currentTime = newTime;

                        seekFeedback.textContent = (seekAmount > 0 ? '⏩ +' : '⏪ ') + 
                            Math.abs(seekAmount).toFixed(1) + 's';
                        seekFeedback.style.display = 'block';

                        clearTimeout(seekTimeout);
                        seekTimeout = setTimeout(() => {
                            seekFeedback.style.display = 'none';
                        }, 1000);

                        e.preventDefault();
                    });

                    video.addEventListener('touchend', () => {
                        isSeeking = false;
                        clearTimeout(seekTimeout);
                        setTimeout(() => {
                            seekFeedback.style.display = 'none';
                        }, 1000);
                    });

                    // 双击暂停/播放
                    let lastTap = 0;
                    video.addEventListener('touchend', (e) => {
                        const currentTime = new Date().getTime();
                        const tapLength = currentTime - lastTap;

                        if (tapLength < 300 && tapLength > 0) {
                            video.paused ? video.play() : video.pause();
                            e.preventDefault();
                        }
                        lastTap = currentTime;
                    });
                }

                // 初始化
                window.addEventListener('DOMContentLoaded', initPlayer);
            </script>
        </body>
        </html>
        `;
